#!/bin/sh
# Issue 48: [MetAcsl] -meta-fold drops the location of the folded instances.
# A folded instance is a call to the generated predicate, built without a
# location, so the assertion has the kernel's generated location: the report
# says "generated by Frama-C kernel" and E-ACSL reports the failure at
# "<unknown>:0". The same property unfolded in the same run keeps the line of
# the meta property. This is a report for the MetAcsl tracker (pub/meta), not
# pub/frama-c.
#
# Image: framac-analysis:latest (Frama-C 34.0~beta, MetAcsl 0.12~beta, with
# E-ACSL, e-acsl-gcc and gcc).
# Command, from this directory:
#   docker run --rm -v "$PWD:/w" -w /w --entrypoint sh framac-analysis:latest \
#     48-metacsl-fold-annotation-location.sh
#
# Output before (34.0~beta, MetAcsl 0.12~beta as installed):
#   34.0~beta (Selenium)
#   report auth_folded:   - Assertion 'meta' (generated by Frama-C kernel)
#   report auth_unfolded: - Assertion 'meta' ("48-metacsl-fold-annotation-location.c", line 35)
#   e-acsl auth_folded:   <unknown>:0: Error: Assertion failed:
#   e-acsl auth_unfolded: 48-metacsl-fold-annotation-location.c:35: Error: Assertion failed:
#   RESULT: the folded instance has no location
#
# Output after, observed with MetAcsl master 4f43801390 plus the patch
# 48-metacsl-fold-annotation-location.patch, built and installed with dune in
# a throwaway container of the same image (the build also needs one line of
# meta_parse.ml removed, the PLpointer_comparable case, which 34.0~beta does
# not have; that is not part of the patch):
#   34.0~beta (Selenium)
#   report auth_folded:   - Assertion 'meta' ("48-metacsl-fold-annotation-location.c", line 30)
#   report auth_unfolded: - Assertion 'meta' ("48-metacsl-fold-annotation-location.c", line 35)
#   e-acsl auth_folded:   48-metacsl-fold-annotation-location.c:30: Error: Assertion failed:
#   e-acsl auth_unfolded: 48-metacsl-fold-annotation-location.c:35: Error: Assertion failed:
#   RESULT: the folded instance has the location of its property
set -u
command -v frama-c >/dev/null 2>&1 || { echo "frama-c is not in PATH" >&2; exit 2; }
n=48-metacsl-fold-annotation-location
here=$(pwd)
tmp=$(mktemp -d)
cp "$n.c" "$tmp/"
cd "$tmp" || exit 2
frama-c -version
frama-c "$n.c" -meta -meta-fold -then-last -report > report.log 2>&1
for p in auth_folded auth_unfolded; do
  printf 'report %-14s %s\n' "$p:" \
    "$(grep -A2 "Meta $p " report.log | sed -n "s/^ *\(- Assertion .*\)/\1/p")"
done
frama-c "$n.c" -meta -meta-fold -then-last -e-acsl -then-last -print -ocode out.c \
  > fc.log 2>&1 || { tail -20 fc.log; exit 2; }
e-acsl-gcc -C -c out.c -O prog > gcc.log 2>&1 || { tail -20 gcc.log; exit 2; }
./prog.e-acsl folded > folded.log 2>&1
./prog.e-acsl > unfolded.log 2>&1
folded=$(grep 'Error: Assertion failed' folded.log)
unfolded=$(grep 'Error: Assertion failed' unfolded.log)
printf 'e-acsl %-14s %s\n' "auth_folded:" "$folded" "auth_unfolded:" "$unfolded"
cd "$here" && rm -rf "$tmp"
case "$folded" in
  "$n.c:30: "*) echo 'RESULT: the folded instance has the location of its property'; exit 0 ;;
  *) echo 'RESULT: the folded instance has no location'; exit 1 ;;
esac
